let hasNativeSegoeFluent = null;
function clientHasSegoeFluentIcons() {
  if (hasNativeSegoeFluent !== null) return hasNativeSegoeFluent;
  try {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      hasNativeSegoeFluent = false;
      return false;
    }
    ctx.font = '32px "Segoe Fluent Icons", monospace';
    const w1 = ctx.measureText('\uE713').width;
    ctx.font = '32px monospace';
    const w2 = ctx.measureText('\uE713').width;
    hasNativeSegoeFluent = w1 !== w2 && w1 > 0;
  } catch {
    hasNativeSegoeFluent = false;
  }
  return hasNativeSegoeFluent;
}

function applyFallbackToElement(el) {
  if (!(el instanceof HTMLElement)) return;
  if (clientHasSegoeFluentIcons()) return;
  const text = (el.textContent || '').trim();
  if (text.length !== 1) return;
  const code = text.codePointAt(0)?.toString(16).toUpperCase() || '';
  const pathData = MISSING_FLUENT_PATHS[code];
  if (!pathData) return;
  if (el.dataset.fiCode === code && el.querySelector('svg.fi-svg')) return;
  el.dataset.fiCode = code;
  el.innerHTML = `<svg class="fi-svg" viewBox="0 0 2048 2048" aria-hidden="true" focusable="false"><path d="${pathData}" fill="currentColor"/></svg>`;
}

function scanAndApply(root) {
  if (!(root instanceof Element || root instanceof Document)) return;
  if (root instanceof HTMLElement && (root.classList.contains('fi') || root.classList.contains('fi-fluent'))) {
    applyFallbackToElement(root);
  }
  root.querySelectorAll('.fi, .fi-fluent').forEach(applyFallbackToElement);
}

let observerInitialized = false;

export function initFluentGlyphFallback(root = document.body) {
  if (!root || clientHasSegoeFluentIcons()) return;
  scanAndApply(root);
  if (observerInitialized) return;
  observerInitialized = true;

  const observer = new MutationObserver((mutations) => {
    for (const m of mutations) {
      if (m.type === 'characterData') {
        const parent = m.target.parentElement;
        if (parent) applyFallbackToElement(parent);
      } else if (m.type === 'childList') {
        if (m.target instanceof HTMLElement && (m.target.classList.contains('fi') || m.target.classList.contains('fi-fluent'))) {
          applyFallbackToElement(m.target);
        }
        m.addedNodes.forEach((node) => {
          if (node instanceof Element) scanAndApply(node);
        });
      }
    }
  });

  observer.observe(root, { childList: true, subtree: true, characterData: true });
}
